#include <iterator>
#include <functional>
#include <cassert>
#include <iostream>

int main() {
    static_assert(std::indirect_equivalence_relation<std::equal_to<>, int *, int *>);
    int values[]{3, 7};
    int *position = values;
    assert(*position == 3);
    ++position;
    assert(*position == 7);
    std::cout << "Checks passed\n";
}
